-- 人工录入舆情新增功能接口

delete from bifrost_role_menu_function where function_id IN (
	select id from bifrost_function where code IN (
	'riskControlOpinionManualClientList','riskControlOpinionManualEntry','riskControlOpinionManualSave','riskControlOpinionManualSubmit','riskControlOpinionManualDelete'
	)
);
delete from bifrost_org_menu_function where function_id IN (
	select id from bifrost_function where code IN (
	'riskControlOpinionManualClientList','riskControlOpinionManualEntry','riskControlOpinionManualSave','riskControlOpinionManualSubmit','riskControlOpinionManualDelete'
	)
);
delete from bifrost_function where code IN (
'riskControlOpinionManualClientList','riskControlOpinionManualEntry','riskControlOpinionManualSave','riskControlOpinionManualSubmit','riskControlOpinionManualDelete'
);

set @menu_id = (select id from bifrost_menu where code = 'riskpublicMonitor');
set @zc_role_id = (select id from bifrost_role where code ='ZCGL');
set @fk_role_id = (select id from bifrost_role where code ='FKJL');
set @zc_org_id = (select id from bifrost_org where code = 'FLHGB_ZCBQ');
set @fk_org_id = (select id from bifrost_org where code = 'FXGLB_YWPS');
set @custom_tree_id = (select id from bifrost_custom_tree_menu_ref where menu_id =@menu_id);
-- 功能添加数据
INSERT INTO bifrost_function ( code, name, sort_no, menu_id, method, path, type)
VALUES ('riskControlOpinionManualClientList', '人工录入舆情-选择客户', 0, @menu_id , 'POST', '/client/list', 1),
		('riskControlOpinionManualEntry', '人工录入舆情-确认', 0, @menu_id , 'POST', '/risk/control/opinion/monitor/confirm', 1),
		('riskControlOpinionManualSave', '人工录入舆情-保存', 0, @menu_id , 'POST', '/risk/control/opinion/monitor/save', 1),
		('riskControlOpinionManualSubmit', '人工录入舆情-提交', 0, @menu_id , 'POST', '/risk/control/opinion/monitor/submit', 1),
		('riskControlOpinionManualDelete', '人工录入舆情-删除', 0, @menu_id , 'POST', '/risk/control/opinion/monitor/delete', 1);

-- 部门添加数据
