-- ============= 来自文件：202602028_linlili_001_dml.sql ============= 


update materials_list ml set materials_type ='OTHER'
where ml.materials_type != 'BASIC_INFORMATION'
and ml.business_type in ('FILING_BUSINESS_CLIENT','FILING_BUSINESS_INNER_OPERATION','FILING_BUSINESS_PAYMENT','FILING_BUSINESS_LEASEHOLD','FILING_BUSINESS_COLLATERALIZATION')
and belong_id in (select id from filing_materials fm where filing_type ='BUSINESS_MATERIALS' and  approve_status ='APPROVAL_PASS' and approve_date is not null);

update filing_first_level_config set docx_enable_flag ='1'
where filing_materials_config_id in (select id from filing_materials_config where filing_type ='BUSINESS_MATERIALS'
and business_type = 'FILING_BUSINESS_INNER_OPERATION');

update filing_first_level_config set enable_flag ='0'
where filing_materials_config_id in (select id from filing_materials_config where filing_type ='BUSINESS_MATERIALS'
and business_type in ('FILING_BUSINESS_LESSEE_CLIENT','FILING_BUSINESS_ENT_CLIENT','FILING_BUSINESS_IND_CLIENT','FILING_BUSINESS_INNER_OPERATION',
'FILING_BUSINESS_PAYMENT','FILING_BUSINESS_LEASEHOLD','FILING_BUSINESS_COLLATERALIZATION') )
and dir_code not in ('BASIC_INFORMATION','OTHER');

update filing_first_level_config set sort_code ='99'
where filing_materials_config_id in (select id from filing_materials_config where filing_type ='BUSINESS_MATERIALS')
and dir_code = 'OTHER';

delete from filing_first_level_config where filing_materials_config_id = (select id from filing_materials_config where business_type ='FILING_BUSINESS_IND_CLIENT' and filing_type ='BUSINESS_MATERIALS') and dir_code ='IND_BASIC_INFORMATION';
INSERT INTO filing_first_level_config (filing_materials_config_id, dir_code, dir_name, fixed_flag, condition_key, sort_code, enable_flag, create_time, create_by, update_time, update_by, require_flag, docx_enable_flag)
VALUES((select id from filing_materials_config where business_type ='FILING_BUSINESS_IND_CLIENT' and filing_type ='BUSINESS_MATERIALS'), 'IND_BASIC_INFORMATION', '基础资料', 1, null, 10, 1, sysdate(), 3, sysdate(), 3, 0, 0);

delete from filing_first_level_config where filing_materials_config_id = (select id from filing_materials_config where business_type ='FILING_BUSINESS_PAYMENT' and filing_type ='BUSINESS_MATERIALS') and dir_code ='SIGN_PHOTO_VIDEO';

