VALUES((select id from filing_materials_config where business_type ='FILING_BUSINESS_PAYMENT' and filing_type ='BUSINESS_MATERIALS'), 'SIGN_PHOTO_VIDEO', '合同签署照片和视频', 0, 'FILE_CHECK', 25, 1, sysdate(), 3, sysdate(), 3, 0, 0);

delete from filing_first_level_config where filing_materials_config_id = (select id from filing_materials_config where business_type ='FILING_BUSINESS_LEASEHOLD' and filing_type ='BUSINESS_MATERIALS') and dir_code  in ('PUBLICITY_INFORMATION','LEASE_RELATED','POLICY');
