delete from bifrost_function where code = 'filingGetCurTaskDefKey';
insert into bifrost_function ( code, name, sort_no, menu_id, create_by, update_by, en_name, `method`, `path`, `type`, group_id)
VALUES('filingGetCurTaskDefKey', '获取当前流程最新审批节点', 0, (select id from bifrost_menu bm where bm.code ='QX0108' and `path` ='/process/receive'), NULL, NULL, 'filingGetCurTaskDefKey', 'POST', '/filingMaterial/getCurTaskDefKey', 1, (select id from gruul_function_group where code = 'QX0108-Read'));

delete from bifrost_role_menu_function where function_id = (select id from bifrost_function where code = 'filingGetCurTaskDefKey');
insert into bifrost_role_menu_function(role_id, menu_id, function_id, custom_tree_id)
select t.role_id, t.menu_id, function2.id, t.custom_tree_id
from
	bifrost_role_menu_function t,
	bifrost_function function,
     bifrost_function function2
where t.function_id = function.id and function.code = 'filingGetTab' and function2.code ='filingGetCurTaskDefKey';
